from pathlib import Path
from datetime import datetime
import base64
import shutil
import py_compile

ROOT = Path.cwd()

REQUIRED = [
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "src/enrichment/consultation_schedule.py",
]

missing = [str(p) for p in REQUIRED if not p.exists()]
if missing:
    print("エラー：clinic-list-filter-complete フォルダで実行してください。")
    print("見つからないファイル:")
    for p in missing:
        print(" -", p)
    raise SystemExit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / f"code_backup_research_v23_{stamp}"
backup.mkdir(parents=True, exist_ok=False)

for p in REQUIRED:
    rel = p.relative_to(ROOT)
    dst = backup / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(p, dst)

exporter = ROOT / "export_research_v23_results.py"
if exporter.exists():
    dst = backup / exporter.name
    shutil.copy2(exporter, dst)

PAYLOADS = {
    'src/scoring/research_scoring.py': '',
    'src/enrichment/consultation_schedule.py': '',
    'export_research_v23_results.py': '',
}

try:
    for rel, encoded in PAYLOADS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))

    # 構文チェック
    py_compile.compile(str(ROOT / "src/scoring/research_scoring.py"), doraise=True)
    py_compile.compile(str(ROOT / "src/enrichment/consultation_schedule.py"), doraise=True)
    py_compile.compile(str(ROOT / "export_research_v23_results.py"), doraise=True)

    (ROOT / "VERSION_RESEARCH").write_text("2.3-research\n", encoding="utf-8")

except Exception as e:
    print("適用中にエラーが発生したため、主要ファイルをバックアップから戻します。")
    for p in REQUIRED:
        rel = p.relative_to(ROOT)
        src = backup / rel
        if src.exists():
            shutil.copy2(src, p)
    print("エラー:", repr(e))
    raise SystemExit(1)

print("修正しました。")
print("・治療カテゴリ v23：医院名 → HOMEの実メニュー/タブ → 医院紹介・診療案内の実メニュー/タブを優先します。")
print("・共通SEOタイトル、サイトマップ、本文に単語があるだけではカテゴリ化しません。")
print("・糖尿病網膜症だけでは糖尿病カテゴリにしません。")
print("・ED/男性更年期だけでは泌尿器科カテゴリにしません。")
print("・独立ページは、HOME/医院紹介等から直接リンクされた治療ページだけ補強根拠にします。")
print("・昼枠 v23：診療時間表で『午前 → 検査/手術/処置 → 午後』が明示されていれば検出します。")
print("・手術行に時刻がなくても、前後の診療時刻から専用枠を推定できます。")
print("・一般診療と並行する検査、重複時刻、壊れた時刻は昼の専用枠にしません。")
print("・年齢推定と広告/集客施策は v22 の改善内容を維持します。")
print("・SQLite、UUID、Google Maps取込結果、Comdesk元データは変更していません。")
print("・比較用出力: export_research_v23_results.py")
print("バックアップ:", backup.name)
